import sys
from collections import deque

def solve():
    # Read the grid
    with open("/workdir/data/input.txt") as f:
        lines = f.read().strip().split("\n")

    grid = []
    for line in lines:
        row = line.split()
        grid.append(row)

    R, C = len(grid), len(grid[0])

    # Find all X cells
    cells = []
    cell_pos = {}
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 'X':
                idx = len(cells)
                cells.append((r, c))
                cell_pos[(r, c)] = idx

    n = len(cells)
    print(f"Number of X cells: {n}")

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for i, (r, c) in enumerate(cells):
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if (nr, nc) in cell_pos:
                adj[i].append(cell_pos[(nr, nc)])

    total_paths = 0
    visited = [False] * n

    def check_connectivity(current_depth):
        """Check if all unvisited cells form one connected component."""
        if current_depth == n:
            return True

        # Find first unvisited cell
        start = -1
        unvisited_count = 0
        for i in range(n):
            if not visited[i]:
                if start == -1:
                    start = i
                unvisited_count += 1

        if unvisited_count == 0:
            return True

        # BFS from start through unvisited cells
        queue = deque([start])
        seen = {start}
        while queue:
            node = queue.popleft()
            for nb in adj[node]:
                if not visited[nb] and nb not in seen:
                    seen.add(nb)
                    queue.append(nb)

        return len(seen) == unvisited_count

    def check_degrees(current_depth):
        """Check if any unvisited cell (except possibly the last one) has 0 unvisited neighbors."""
        if current_depth >= n - 1:
            return True

        for i in range(n):
            if not visited[i]:
                deg = 0
                for nb in adj[i]:
                    if not visited[nb]:
                        deg += 1
                if deg == 0:
                    return False
        return True

    def backtrack(node, depth):
        nonlocal total_paths
        if depth == n:
            total_paths += 1
            return

        # Get unvisited neighbors with Warnsdorff ordering
        neighbors = []
        for nb in adj[node]:
            if not visited[nb]:
                cnt = 0
                for nnb in adj[nb]:
                    if not visited[nnb]:
                        cnt += 1
                neighbors.append((cnt, nb))
        neighbors.sort()

        for _, nb in neighbors:
            visited[nb] = True
            # Pruning checks
            if check_degrees(depth + 1):
                if check_connectivity(depth + 1):
                    backtrack(nb, depth + 1)
            visited[nb] = False

    import time
    start_time = time.time()

    for start in range(n):
        visited[start] = True
        if check_degrees(1):
            if check_connectivity(1):
                backtrack(start, 1)
        visited[start] = False
        elapsed = time.time() - start_time
        print(f"After starting cell {start}: {total_paths} paths, {elapsed:.1f}s")

    print(f"Total directed paths: {total_paths}")
    print(f"Unique paths (divided by 2): {total_paths // 2}")

    with open("/workdir/sol.txt", "w") as f:
        f.write(str(total_paths // 2))

solve()
